// Minimal HTMX-compatible implementation for ACS Archive Browser.
// Supports: hx-get, hx-post, hx-trigger, hx-target, hx-swap, hx-include.
(function() {
  'use strict';

  function getTarget(el, attr) {
    var sel = el.getAttribute(attr);
    if (!sel) return null;
    if (sel === 'this') return el;
    return document.querySelector(sel);
  }

  function getIncludeValues(el, includeSelector) {
    var params = new URLSearchParams();
    if (!includeSelector) return params;
    var scope = el.closest('form') || document;
    document.querySelectorAll(includeSelector).forEach(function(inp) {
      if (inp.name && inp.value) params.set(inp.name, inp.value);
    });
    return params;
  }

  function doRequest(el, method, url, extraParams) {
    var target = getTarget(el, 'hx-target') || el;
    var swap = el.getAttribute('hx-swap') || 'innerHTML';
    var includeSelector = el.getAttribute('hx-include');
    var params = getIncludeValues(el, includeSelector);

    // Also include own value if input.
    if (el.name && el.value !== undefined) {
      params.set(el.name, el.value);
    }
    if (extraParams) {
      extraParams.forEach(function(v, k) { params.set(k, v); });
    }

    var fetchUrl = url;
    var fetchOpts = { headers: { 'HX-Request': 'true' } };
    if (method === 'GET') {
      if (params.toString()) fetchUrl += (url.includes('?') ? '&' : '?') + params.toString();
    } else {
      fetchOpts.method = 'POST';
      fetchOpts.body = params;
    }

    fetch(fetchUrl, fetchOpts).then(function(r) { return r.text(); }).then(function(html) {
      if (swap === 'outerHTML') {
        var tmp = document.createElement('div');
        tmp.innerHTML = html;
        target.replaceWith(tmp.firstElementChild || tmp);
      } else {
        target.innerHTML = html;
      }
    }).catch(function(e) { console.error('htmx request failed', e); });
  }

  function attachTrigger(el) {
    var trigger = el.getAttribute('hx-trigger') || 'click';
    var url = el.getAttribute('hx-get') || el.getAttribute('hx-post');
    var method = el.getAttribute('hx-get') ? 'GET' : 'POST';
    if (!url) return;

    var timers = {};

    function fire() {
      doRequest(el, method, url, null);
    }

    // Parse trigger: e.g. "input changed delay:400ms, search"
    trigger.split(',').forEach(function(part) {
      part = part.trim();
      var delayMs = 0;
      var delayMatch = part.match(/delay:(\d+)ms/);
      if (delayMatch) delayMs = parseInt(delayMatch[1], 10);
      var evtName = part.split(' ')[0];

      el.addEventListener(evtName, function() {
        if (delayMs > 0) {
          clearTimeout(timers[evtName]);
          timers[evtName] = setTimeout(fire, delayMs);
        } else {
          fire();
        }
      });
    });
  }

  function attachForm(form) {
    var url = form.getAttribute('hx-post');
    if (!url) return;
    form.addEventListener('submit', function(e) {
      e.preventDefault();
      var params = new URLSearchParams(new FormData(form));
      doRequest(form, 'POST', url, params);
    });
  }

  function init() {
    document.querySelectorAll('[hx-get],[hx-post]').forEach(function(el) {
      if (el.tagName === 'FORM') {
        attachForm(el);
      } else {
        attachTrigger(el);
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
